tool_args.command:
python3 -c '
import csv
from datetime import datetime

with open("data/orders_2026_05.csv", newline="") as handle:
    reader = csv.DictReader(handle)
    for line, row in enumerate(reader, start=2):
        problems = []
        if not row["order_id"].strip():
            problems.append("order_id blank")
        try:
            int(row["amount_cents"])
        except ValueError:
            problems.append("amount " + repr(row["amount_cents"]))
        discount = row["discount_cents"].strip()
        if discount:
            try:
                int(discount)
            except ValueError:
                problems.append("discount " + repr(discount))
        try:
            datetime.strptime(row["placed_at"], "%d/%m/%Y")
        except ValueError:
            problems.append("date " + repr(row["placed_at"]))
        if problems:
            print(line, problems)
'
